import json,pathlib,sys
bad=[f for f in ('conformance/README.md','conformance/schema.md') if not pathlib.Path(f).is_file()]
cs=sorted(pathlib.Path('conformance/cases/example').glob('*/case.json'))
if len(cs)<2: bad.append(f'{len(cs)} cas example (<2)')
keys={'id','title','provenance','validates','tolerance','status'}
for c in cs:
    miss=keys-set(json.loads(c.read_text(encoding='utf-8')))
    if miss: bad.append(f'{c}: champs manquants {sorted(miss)}')
print('\n'.join(bad) or 'OK'); sys.exit(1 if bad else 0)

import json,pathlib,sys
cs=sorted(pathlib.Path('conformance/cases/base').glob('*/case.json'))
bad=[] if len(cs)>=10 else [f'{len(cs)} cas base (<10)']
for c in cs:
    d=json.loads(c.read_text(encoding='utf-8')); pv=d.get('provenance') or {}
    if d.get('status') not in ('validated','known-divergence'): bad.append(f'{c}: status')
    if pv.get('kind') not in ('sas-doc','sas-run'): bad.append(f'{c}: provenance.kind')
    if pv.get('kind')=='sas-doc' and not str(pv.get('source','')).startswith('http'): bad.append(f'{c}: URL')
print('\n'.join(bad) or f'OK: {len(cs)} cas'); sys.exit(1 if bad else 0)

import json,pathlib,sys
