import json,pathlib,sys
root=pathlib.Path('conformance/cases/compat'); bad=[]
for g in ['means', 'compare', 'transpose', 'printto', 'informat']:
    cs=sorted((root/g).glob('*/case.json'))
    if len(cs)<2: bad.append(f'{g}: {len(cs)} cas (<2)')
    for c in cs:
        d=json.loads(c.read_text(encoding='utf-8')); pv=d.get('provenance') or {}
        if pv.get('kind')!='sas-doc' or not str(pv.get('source','')).startswith('http'): bad.append(f'{c}: provenance sas-doc + URL')
        if d.get('status') not in ('validated','known-divergence'): bad.append(f'{c}: status')
if not (root/'ORACLE.sha256').is_file(): bad.append('ORACLE.sha256 absent')
print('\n'.join(bad) or 'OK'); sys.exit(1 if bad else 0)

import hashlib,pathlib,sys
root=pathlib.Path('conformance/cases/compat'); want={}
for line in (root/'ORACLE.sha256').read_text(encoding='utf-8').splitlines():
    if line.strip():
        h,p=line.split('  ',1); want[p]=h
have={p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in root.rglob('*') if p.is_file() and p.name not in ('case.json','ORACLE.sha256')}
diff=sorted(k for k in set(want)|set(have) if want.get(k)!=have.get(k))
print('\n'.join(diff) or f'OK: {len(have)} fichiers oracle inchangés'); sys.exit(1 if diff or not have else 0)
